}

function ukurWaktu<A extends unknown[], R>(nama: string, fn: (...a: A) => R) {
  return (...a: A): R => {
    const t0 = performance.now();
    const r = fn(...a);
    console.log(`${nama} selesai dalam ${(performance.now() - t0) < 50 ? "< 50" : "> 50"} ms`);
    return r;
  };
}
