function bubbleSort<T>(data: readonly T[], banding: (a: T, b: T) => number) {
  const a = [...data];
  let banding_ = 0, tukar = 0;
  for (let i = 0; i < a.length - 1; i++) {
    let adaTukar = false;
    for (let j = 0; j < a.length - 1 - i; j++) {
      banding_++;
      if (banding(a[j], a[j + 1]) > 0) { [a[j], a[j + 1]] = [a[j + 1], a[j]]; tukar++; adaTukar = true; }
    }
    if (!adaTukar) break;
  }
  return { hasil: a, banding: banding_, tukar };
}
const harga = [45000, 12000, 87000, 30000, 5000, 61000];
const r = bubbleSort(harga, (x, y) => x - y);
console.log(r.hasil.join(" "), `| ${r.banding} perbandingan, ${r.tukar} pertukaran`);
const urut = bubbleSort(r.hasil, (x, y) => x - y);
console.log("data sudah urut:", urut.banding, "perbandingan (early exit)");
const nama = bubbleSort(["Sari", "andi", "Budi"], (x, y) => x.localeCompare(y, "id"));
console.log(nama.hasil.join(", "));

fizzbuzz-dan-bilangan-prima-break-dan-lo.code:
function fizzBuzz(n: number): string[] {
  const hasil: string[] = [];
  for (let i = 1; i <= n; i++) {            // FOR: rentang jelas
    if (i % 15 === 0) hasil.push("FizzBuzz");
    else if (i % 3 === 0) hasil.push("Fizz");
    else if (i % 5 === 0) hasil.push("Buzz");
    else hasil.push(String(i));
  }
  return hasil;
}

function isPrima(x: number): boolean {
  if (x < 2) return false;
  for (let d = 2; d * d <= x; d++) {
    if (x % d === 0) return false;          // keluar lebih awal
  }
  return true;
}

console.log(fizzBuzz(15).join(" "));
const prima: number[] = [];
for (let x = 2; x <= 30; x++) if (isPrima(x)) prima.push(x);
console.log("Prima:", prima.join(" "));

