function saringan(n: number): number[] {
  const p = new Array<boolean>(n + 1).fill(true); p[0] = p[1] = false;
  for (let i = 2; i * i <= n; i++) if (p[i]) for (let j = i * i; j <= n; j += i) p[j] = false;
  return p.flatMap((ok, i) => (ok ? [i] : []));
}
